+function diffLines(a, b) {
+  if (!Array.isArray(a) || !Array.isArray(b)) {
+    throw new TypeError('diffLines expects two arrays of strings');
+  }
+  const n = a.length;
+  const m = b.length;
+
+  // Intern lines as integers so the inner loops compare numbers, not strings.
+  const ids = new Map();
+  const ai = new Int32Array(n);
+  const bi = new Int32Array(m);
+  for (let i = 0; i < n; i++) {
+    let id = ids.get(a[i]);
+    if (id === undefined) {
+      id = ids.size;
+      ids.set(a[i], id);
+    }
+    ai[i] = id;
+  }
+  const aIdCount = ids.size;
+  let shared = false;
+  for (let j = 0; j < m; j++) {
+    let id = ids.get(b[j]);
+    if (id === undefined) {
+      id = ids.size;
+      ids.set(b[j], id);
+    } else if (id < aIdCount) {
+      shared = true;
+    }
+    bi[j] = id;
+  }
+
+  // Matched (equal) index pairs in increasing order.
+  const matchA = [];
+  const matchB = [];
+  if (shared) {
+    const vSize = n + m + 2;
+    const v1 = new Int32Array(vSize);
+    const v2 = new Int32Array(vSize);
+    solve(ai, bi, 0, n, 0, m, v1, v2, matchA, matchB);
+  }
+
+  const script = [];
+  let i = 0;
+  let j = 0;
+  for (let p = 0; p < matchA.length; p++) {
+    const x = matchA[p];
+    const y = matchB[p];
+    while (i < x) script.push({ op: 'delete', line: a[i++] });
+    while (j < y) script.push({ op: 'insert', line: b[j++] });
+    script.push({ op: 'equal', line: a[i] });
+    i++;
+    j++;
+  }
+  while (i < n) script.push({ op: 'delete', line: a[i++] });
+  while (j < m) script.push({ op: 'insert', line: b[j++] });
+  return script;
+}
+
+/**
+ * Record a longest common subsequence of a[aLo, aHi) and b[bLo, bHi) into
+ * matchA/matchB in order, using Myers' linear-space middle-snake bisection.
+ */
+function solve(a, b, aLo, aHi, bLo, bHi, v1, v2, matchA, matchB) {
+  // Common prefix.
+  while (aLo < aHi && bLo < bHi && a[aLo] === b[bLo]) {
+    matchA.push(aLo++);
+    matchB.push(bLo++);
+  }
+  // Common suffix (recorded after the middle is solved).
+  let suffix = 0;
+  while (aLo < aHi - suffix && bLo < bHi - suffix &&
+         a[aHi - suffix - 1] === b[bHi - suffix - 1]) {
+    suffix++;
+  }
+  const aEnd = aHi - suffix;
+  const bEnd = bHi - suffix;
+
+  if (aLo < aEnd && bLo < bEnd) {
+    const split = bisect(a, b, aLo, aEnd, bLo, bEnd, v1, v2);
+    if (split !== null) {
+      solve(a, b, aLo, split[0], bLo, split[1], v1, v2, matchA, matchB);
+      solve(a, b, split[0], aEnd, split[1], bEnd, v1, v2, matchA, matchB);
+    }
+  }
+
+  for (let s = 0; s < suffix; s++) {
+    matchA.push(aEnd + s);
+    matchB.push(bEnd + s);
+  }
+}
+
+/**
+ * Find a split point on a minimal edit path between a[aLo, aHi) and
+ * b[bLo, bHi), whose first and last elements differ. Returns [x, y] in
+ * absolute coordinates, or null if the ranges share no common element.
+ */
+function bisect(a, b, aLo, aHi, bLo, bHi, v1, v2) {
+  const n = aHi - aLo;
+  const m = bHi - bLo;
+  const maxD = Math.ceil((n + m) / 2);
+  const off = maxD;
+  const vLen = 2 * maxD + 2;
+  v1.fill(-1, 0, vLen);
+  v2.fill(-1, 0, vLen);
+  v1[off + 1] = 0;
+  v2[off + 1] = 0;
+  const delta = n - m;
+  const front = (delta & 1) !== 0;
+  let k1start = 0;
+  let k1end = 0;
+  let k2start = 0;
+  let k2end = 0;
+
+  for (let d = 0; d < maxD; d++) {
+    // Forward search.
+    for (let k1 = -d + k1start; k1 <= d - k1end; k1 += 2) {
+      const k1o = off + k1;
+      let x1;
+      if (k1 === -d || (k1 !== d && v1[k1o - 1] < v1[k1o + 1])) {
+        x1 = v1[k1o + 1];
+      } else {
+        x1 = v1[k1o - 1] + 1;
+      }
+      let y1 = x1 - k1;
+      while (x1 < n && y1 < m && a[aLo + x1] === b[bLo + y1]) {
+        x1++;
+        y1++;
+      }
+      v1[k1o] = x1;
+      if (x1 > n) {
+        k1end += 2;
+      } else if (y1 > m) {
+        k1start += 2;
+      } else if (front) {
+        const k2o = off + delta - k1;
+        if (k2o >= 0 && k2o < vLen && v2[k2o] !== -1) {
+          if (x1 >= n - v2[k2o]) return [aLo + x1, bLo + y1];
+        }
+      }
+    }
+    // Reverse search.
+    for (let k2 = -d + k2start; k2 <= d - k2end; k2 += 2) {
+      const k2o = off + k2;
+      let x2;
+      if (k2 === -d || (k2 !== d && v2[k2o - 1] < v2[k2o + 1])) {
+        x2 = v2[k2o + 1];
+      } else {
+        x2 = v2[k2o - 1] + 1;
+      }
+      let y2 = x2 - k2;
+      while (x2 < n && y2 < m && a[aHi - x2 - 1] === b[bHi - y2 - 1]) {
+        x2++;
+        y2++;
+      }
+      v2[k2o] = x2;
+      if (x2 > n) {
+        k2end += 2;
+      } else if (y2 > m) {
+        k2start += 2;
+      } else if (!front) {
+        const k1o = off + delta - k2;
+        if (k1o >= 0 && k1o < vLen && v1[k1o] !== -1) {
+          const x1 = v1[k1o];
+          const y1 = off + x1 - k1o;
+          if (x1 >= n - x2) return [aLo + x1, bLo + y1];
+        }
+      }
+    }
+  }
+  return null;
+}
