+function unifiedHunks(a, b, { context = 3 } = {}) {
+  if (!Number.isInteger(context) || context < 0) {
+    throw new RangeError('context must be a nonnegative integer');
+  }
+  const ops = diffLines(a, b);
+  const len = ops.length;
+
+  // Maximal runs of non-equal ops: [start, end) indexes into ops.
+  const regions = [];
+  for (let p = 0; p < len;) {
+    if (ops[p].op === 'equal') {
+      p++;
+      continue;
+    }
+    const start = p;
+    while (p < len && ops[p].op !== 'equal') p++;
+    regions.push([start, p]);
+  }
+  if (regions.length === 0) return [];
+
+  // Group regions whose unchanged gap is <= 2 * context.
+  const groups = [];
+  let cur = [regions[0][0], regions[0][1]];
+  for (let r = 1; r < regions.length; r++) {
+    if (regions[r][0] - cur[1] <= 2 * context) {
+      cur[1] = regions[r][1];
+    } else {
+      groups.push(cur);
+      cur = [regions[r][0], regions[r][1]];
+    }
+  }
+  groups.push(cur);
+
+  const hunks = [];
+  let p = 0;
+  let oldPos = 0;
+  let newPos = 0;
+  for (const [gStart, gEnd] of groups) {
+    const from = Math.max(0, gStart - context);
+    const to = Math.min(len, gEnd + context);
+    // Advance positions up to the hunk start (only equal ops lie here).
+    for (; p < from; p++) {
+      oldPos++;
+      newPos++;
+    }
+    const hunkOld = oldPos;
+    const hunkNew = newPos;
+    const lines = [];
+    for (; p < to; p++) {
+      const { op, line } = ops[p];
+      if (op === 'equal') {
+        lines.push(' ' + line);
+        oldPos++;
+        newPos++;
+      } else if (op === 'delete') {
+        lines.push('-' + line);
+        oldPos++;
+      } else {
+        lines.push('+' + line);
+        newPos++;
+      }
+    }
+    const oldLines = oldPos - hunkOld;
+    const newLines = newPos - hunkNew;
+    hunks.push({
+      oldStart: oldLines === 0 ? hunkOld : hunkOld + 1,
+      oldLines,
+      newStart: newLines === 0 ? hunkNew : hunkNew + 1,
+      newLines,
+      lines,
+    });
+  }
+  return hunks;
+}
