  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  return dp[0][0];
}
let seed = 12345;
const rnd = (k) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % k; };
const alpha = ['', 'x', 'y', ' x', '-x', '+x', 'z'];
const gen = () => Array.from({ length: rnd(14) }, () => alpha[rnd(alpha.length)]);

for (let t = 0; t < 20000; t++) {
  const a = gen(), b = gen();
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s, diffLines(a, b));
  assert.deepEqual(s.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(s.filter(e => e.op !== 'delete').map(e => e.line), b);
  const edits = s.filter(e => e.op !== 'equal').length;
  assert.equal(edits, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  for (const context of [0, 1, 2, 3]) {
    const hs = unifiedHunks(a, b, { context });
    if (edits === 0) assert.deepEqual(hs, []);
    assert.deepEqual(applyHunks(a, hs), b);
    for (const h of hs) {
      const oldL = h.lines.filter(l => l[0] !== '+').map(l => l.slice(1));
      const newL = h.lines.filter(l => l[0] !== '-').map(l => l.slice(1));
      const o = h.oldLines ? h.oldStart - 1 : h.oldStart;
      const n = h.newLines ? h.newStart - 1 : h.newStart;
      assert.deepEqual(a.slice(o, o + h.oldLines), oldL);
      assert.deepEqual(b.slice(n, n + h.newLines), newL);
    }
    // tamper -> must throw with index
    if (hs.length) {
      const k = rnd(hs.length);
      const bad = hs.map(h => ({ ...h, lines: h.lines.slice() }));
      const li = bad[k].lines.findIndex(l => l[0] !== '+');
      if (li >= 0) {
        bad[k].lines[li] = bad[k].lines[li][0] + 'NOPE';
        assert.throws(() => applyHunks(a, bad), new RegExp(`hunk ${k} does not apply`));
      }
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}

// perf
const big = Array.from({ length: 20000 }, (_, i) => 'line ' + (i % 50));
const big2 = big.slice(); big2[100] = 'changed'; big2.splice(9000, 3); big2.splice(15000, 0, 'new', 'lines');
let t0 = Date.now();
const hs = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hs), big2);
console.log('repetitive small change ms', Date.now() - t0, 'hunks', hs.length);
const rep = Array(20000).fill('same');
t0 = Date.now();
assert.deepEqual(applyHunks(rep, unifiedHunks(rep, rep.slice(0, 19990).concat(['x']))), rep.slice(0, 19990).concat(['x']));
console.log('all-identical ms', Date.now() - t0);
const scattered = big.map((l, i) => (i % 500 === 0 ? 'edit' + i : l));
t0 = Date.now();
const d = diffLines(big, scattered);
assert.equal(d.filter(e => e.op !== 'equal').length, 80);
console.log('scattered ms', Date.now() - t0);
console.log('ok');

